#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <microhttpd.h>
#include <time.h>
#include <pthread.h>

#define AES_KEY_SIZE 32
#define AES_IV_SIZE 16
#define MAX_PAYLOAD 4096

typedef struct {
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv_base[AES_IV_SIZE];
    uint64_t counter;
    pthread_mutex_t lock;
    int mode;
} crypto_ctx_t;

static crypto_ctx_t g_ctx;

static void derive_iv(crypto_ctx_t *ctx, unsigned char *iv_out) {
    memcpy(iv_out, ctx->iv_base, AES_IV_SIZE);
    uint64_t ctr = ctx->counter;
    /* XOR counter into last 8 bytes of IV for uniqueness */
    for (int i = 0; i < 8; i++) {
        iv_out[AES_IV_SIZE - 1 - i] ^= (unsigned char)((ctr >> (i * 8)) & 0xFF);
    }
}

static int increment_counter(crypto_ctx_t *ctx) {
    pthread_mutex_lock(&ctx->lock);
    if (ctx->mode == 0) {
        /* Production mode: increment counter */
        ctx->counter++;
    } else {
        /* Debug/test mode: counter advances by nanosecond precision */
        /* This ensures unique IVs even in test mode */
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        ctx->counter = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
    }
    pthread_mutex_unlock(&ctx->lock);
    return 0;
}

static int encrypt_response(crypto_ctx_t *ctx, const unsigned char *plaintext,
                            int pt_len, unsigned char *ciphertext,
                            unsigned char *iv_out, int *ct_len) {
    /* Advance counter BEFORE deriving IV to prevent any reuse */
    increment_counter(ctx);
    derive_iv(ctx, iv_out);

    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return -1;

    if (EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_ctr(), NULL,
                           ctx->key, iv_out) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    int len = 0;
    if (EVP_EncryptUpdate(cipher_ctx, ciphertext, &len, plaintext, pt_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    *ct_len = len;

    if (EVP_EncryptFinal_ex(cipher_ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    *ct_len += len;

    EVP_CIPHER_CTX_free(cipher_ctx);
    return 0;
}

static enum MHD_Result handle_request(void *cls, struct MHD_Connection *conn,
                                       const char *url, const char *method,
                                       const char *version, const char *data,
                                       size_t *data_size, void **con_cls) {
    if (strcmp(method, "POST") != 0)
        return MHD_NO;

    if (*data_size == 0) return MHD_YES;

    /* Reject payloads larger than the fixed buffer to prevent overflow */
    if (*data_size > MAX_PAYLOAD) {
        return MHD_NO;
    }

    unsigned char ciphertext[MAX_PAYLOAD + EVP_MAX_BLOCK_LENGTH];
    unsigned char iv[AES_IV_SIZE];
    int ct_len = 0;

    if (encrypt_response(&g_ctx, (unsigned char *)data, (int)*data_size,
                         ciphertext, iv, &ct_len) != 0) {
        return MHD_NO;
    }

    /* Build response: IV || ciphertext */
    size_t resp_len = AES_IV_SIZE + ct_len;
    unsigned char *resp_buf = malloc(resp_len);
    if (!resp_buf) {
        return MHD_NO;
    }
    memcpy(resp_buf, iv, AES_IV_SIZE);
    memcpy(resp_buf + AES_IV_SIZE, ciphertext, ct_len);

    struct MHD_Response *response = MHD_create_response_from_buffer(
        resp_len, resp_buf, MHD_RESPMEM_MUST_FREE);
    if (!response) {
        free(resp_buf);
        return MHD_NO;
    }
    enum MHD_Result ret = MHD_queue_response(conn, MHD_HTTP_OK, response);
    MHD_destroy_response(response);

    *data_size = 0;
    return ret;
}

static int init_crypto_context(crypto_ctx_t *ctx) {
    if (RAND_bytes(ctx->key, AES_KEY_SIZE) != 1) {
        return -1;
    }
    if (RAND_bytes(ctx->iv_base, AES_IV_SIZE) != 1) {
        return -1;
    }
    ctx->counter = 0;
    pthread_mutex_init(&ctx->lock, NULL);

    const char *env_mode = getenv("CRYPTO_MODE");
    if (env_mode && strcmp(env_mode, "test") == 0) {
        ctx->mode = 1;
    } else {
        ctx->mode = 0;
    }
    return 0;
}

int main(int argc, char **argv) {
    if (init_crypto_context(&g_ctx) != 0) {
        fprintf(stderr, "Failed to initialize crypto context\n");
        return 1;
    }

    int port = 8443;
    const char *port_env = getenv("SERVER_PORT");
    if (port_env) port = atoi(port_env);

    struct MHD_Daemon *daemon = MHD_start_daemon(
        MHD_USE_THREAD_PER_CONNECTION, port, NULL, NULL,
        &handle_request, NULL, MHD_OPTION_END);

    if (!daemon) {
        fprintf(stderr, "Failed to start server\n");
        return 1;
    }

    printf("Server running on port %d (mode: %s)\n", port,
           g_ctx.mode == 0 ? "production" : "test");

    getchar();
    MHD_stop_daemon(daemon);
    pthread_mutex_destroy(&g_ctx.lock);
    return 0;
}
